    "text": "{\"results\": [{\"id\": \"sheets.spreadsheets.values.append\", \"method\": \"POST\", \"description\": \"Insert new rows of data into a spreadsheet following the last occupied row in the given range.\", \"parameters\": {\"spreadsheetId\": {\"type\": \"string\", \"description\": \"Identifier of the target spreadsheet.\", \"required\": true, \"location\": \"path\"}, \"range\": {\"type\": \"string\", \"description\": \"A1-notation range indicating where to append data (e.g., 'Sheet1!A1:E1').\", \"required\": true, \"location\": \"path\"}, \"valueInputOption\": {\"type\": \"string\", \"enum\": [\"RAW\", \"USER_ENTERED\"], \"description\": \"How the input should be interpreted (required). USER_ENTERED parses formulas and values; RAW inserts text as-is.\", \"required\": true, \"location\": \"query\"}, \"insertDataOption\": {\"type\": \"string\", \"enum\": [\"OVERWRITE\", \"INSERT_ROWS\"], \"description\": \"Determines whether existing rows are overwritten or new rows are inserted (default OVERWRITE).\", \"required\": false, \"location\": \"query\"}}, \"request\": \"{range: string, majorDimension?: string, values: [[cell, ...], ...]}\", \"response\": \"{spreadsheetId, tableRange, updates: {spreadsheetId, updatedRange, updatedRows, updatedColumns, updatedCells}}\", \"url\": \"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheetId}/values/{range}:append\"}, {\"id\": \"sheets.spreadsheets.sheets.copyTo\", \"method\": \"POST\", \"description\": \"Duplicate a sheet tab into a different spreadsheet.\", \"parameters\": {\"spreadsheetId\": {\"type\": \"string\", \"description\": \"Identifier of the source spreadsheet.\", \"required\": true, \"location\": \"path\"}, \"sheetId\": {\"type\": \"integer\", \"description\": \"Numeric ID of the sheet to duplicate.\", \"required\": true, \"location\": \"path\"}}, \"request\": \"{destinationSpreadsheetId: string (required, target spreadsheet ID)}\", \"response\": \"{sheetId, title, index, sheetType}\", \"url\": \"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheetId}/sheets/{sheetId}:copyTo\"}, {\"id\": \"sheets.spreadsheets.get\", \"method\": \"GET\", \"description\": \"Retrieve a spreadsheet by its ID. Returns document metadata, sheet listings, and optionally the grid cell data.\", \"parameters\": {\"spreadsheetId\": {\"type\": \"string\", \"description\": \"Identifier of the spreadsheet to retrieve.\", \"required\": true, \"location\": \"path\"}, \"includeGridData\": {\"type\": \"boolean\", \"description\": \"Whether to include cell-level data in the response (default false).\", \"required\": false, \"location\": \"query\"}, \"ranges\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Specific ranges to retrieve from the spreadsheet in A1 notation (e.g., 'Sheet1!A1:B5').\", \"required\": false, \"location\": \"query\"}}, \"response\": \"Spreadsheet: {spreadsheetId, properties: {title}, sheets: [{properties: {sheetId, title, index, sheetType}, data}], spreadsheetUrl}\", \"url\": \"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheetId}\"}, {\"id\": \"bamboohr.employees.tables.changed\", \"method\": \"GET\", \"description\": \"Retrieve table rows that have been modified since a specified point in time, organized by employee ID.\", \"parameters\": {\"table\": {\"type\": \"string\", \"description\": \"Name of the table to check for changes (e.g., jobInfo, compensation).\", \"required\": true, \"location\": \"path\"}, \"since\": {\"type\": \"string\", \"format\": \"date-time\", \"description\": \"ISO 8601 timestamp (URL-encoded). Only rows changed after this moment are included.\", \"required\": true, \"location\": \"query\"}}, \"response\": \"Changed table rows grouped by employee ID with last-changed timestamps.\", \"url\": \"https://api.bamboohr.com/api/gateway.php/{companyDomain}/bamboohr/v1/employees/changed/tables/{table}\"}, {\"id\": \"sheets.spreadsheets.batchUpdate\", \"method\": \"POST\", \"description\": \"Execute one or more structural changes on a spreadsheet in one request. Supports adding sheets (AddSheetRequest), deleting sheets (DeleteSheetRequest), renaming sheets (UpdateSheetPropertiesRequest), and other layout operations.\", \"parameters\": {\"spreadsheetId\": {\"type\": \"string\", \"description\": \"Identifier of the target spreadsheet.\", \"required\": true, \"location\": \"path\"}}, \"request\": \"{requests: [{addSheet?: {properties: {title: string, index?: int}}, deleteSheet?: {sheetId: int}, updateSheetProperties?: {properties: {sheetId: int, title?: string, index?: int}, fields: string (e.g. 'title')}}]}\", \"response\": \"{spreadsheetId, replies: [{addSheet?: {properties: {sheetId, title, index, sheetType}}}]}\", \"url\": \"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheetId}:batchUpdate\"}], \"count\": 5}"
  }
]

