e/{estimateId}/send\"}, {\"id\": \"gmail.users.messages.send\", \"method\": \"POST\", \"description\": \"Compose and deliver an email to one or more recipients.\", \"parameters\": {\"userId\": {\"type\": \"string\", \"required\": true, \"location\": \"path\", \"default\": \"me\"}}, \"request\": \"Message with raw (RFC 2822 base64url) or payload with headers and body\", \"response\": \"Sent Message with id, threadId, labelIds\", \"url\": \"https://gmail.googleapis.com/gmail/v1/users/{userId}/messages/send\"}, {\"id\": \"xero.invoices.email\", \"method\": \"POST\", \"description\": \"Send an invoice to the contact's email address. The invoice must be in AUTHORISED or SUBMITTED status.\", \"parameters\": {\"InvoiceID\": {\"type\": \"string\", \"required\": true, \"location\": \"path\"}}, \"response\": \"204 No Content on success\", \"url\": \"https://api.xero.com/api.xro/2.0/Invoices/{InvoiceID}/Email\"}], \"count\": 5}"
