nged with candidates.\", \"parameters\": {\"company_id\": {\"type\": \"integer\", \"required\": true, \"location\": \"path\"}, \"candidate_id\": {\"type\": \"integer\", \"description\": \"Filter to messages for a specific candidate.\", \"location\": \"query\"}}, \"response\": \"{messages: [MailboxMessage, ...]}\", \"url\": \"https://api.recruitee.com/c/{company_id}/recruitee/v1/c/{company_id}/mailbox/messages\"}, {\"id\": \"trello.cards.addLabel\", \"method\": \"POST\", \"description\": \"Attach a label to a Trello card using its label ID. Label IDs can be found via GET /1/boards/{id}/labels.\", \"parameters\": {\"id\": {\"type\": \"string\", \"description\": \"Identifier of the card.\", \"required\": true, \"location\": \"path\"}, \"value\": {\"type\": \"string\", \"description\": \"The label ID to attach to the card.\", \"required\": true, \"location\": \"body\"}}, \"response\": \"[{id, idBoard, name, color}]\", \"url\": \"https://api.trello.com/1/cards/{id}/idLabels\"}, {\"id\": \"intercom.conversations.list\", \"method\": \"GET\", \"description\": \"Retrieve all Intercom conversations, threads, and messages. Fetch support interaction records.\", \"parameters\": {}, \"response\": \"{conversations: [ConversationObject], count: int}\", \"url\": \"https://api.intercom.io/conversations\"}], \"count\": 5}"
