    "text": "{\"results\": [{\"id\": \"salesforce.sobjects.document.create\", \"method\": \"POST\", \"description\": \"Store a Document inside a Salesforce Folder.\", \"parameters\": {}, \"request\": \"Document fields: {FolderId (required), Name (required), Body (required - file content), Description, Keywords}\", \"response\": \"{id: string, success: true}\", \"url\": \"https://yourinstance.salesforce.com/services/data/v61.0/sobjects/Document\"}, {\"id\": \"bamboohr.files.company.upload\", \"method\": \"POST\", \"description\": \"Upload a new company-level document.\", \"parameters\": {}, \"request\": \"Multipart form: fileName (string, required), category (integer, required \\u2014 file section ID), file (binary, required \\u2014 max 20MB).\", \"response\": \"201 Created with Location header.\", \"url\": \"https://api.bamboohr.com/api/gateway.php/{companyDomain}/bamboohr/v1/files\"}, {\"id\": \"openai.moderations.create\", \"method\": \"POST\", \"description\": \"Screen text for policy violations. Produces per-category flags along with confidence scores. Use this to verify that content complies with OpenAI usage policies before passing it to a model.\", \"parameters\": {}, \"request\": \"Body: {input (required, string or array of strings to classify), model (optional, default 'omni-moderation-latest' \\u2014 also supports 'text-moderation-latest', 'text-moderation-stable')}\", \"response\": \"{id, model, results: [{flagged: boolean, categories: {sexual, hate, harassment, harassment/threatening, self-harm, self-harm/intent, self-harm/instructions, sexual/minors, hate/threatening, violence, violence/graphic, illicit, illicit/violent}, category_scores: {same keys, float 0.0\\u20131.0}}]}\", \"url\": \"https://api.openai.com/v1/moderations\"}, {\"id\": \"instagram.media.getContainerStatus\", \"method\": \"GET\", \"description\": \"Check the processing status of a media container created in step 1. Poll this endpoint until status_code returns FINISHED before proceeding to media_publish. This step is mandatory for video and reel containers, which require processing time.\", \"parameters\": {\"containerId\": {\"type\": \"string\", \"description\": \"The container ID returned by the createContainer operation.\", \"required\": true, \"location\": \"path\"}, \"fields\": {\"type\": \"string\", \"description\": \"Comma-separated field names to include in the response (e.g. 'id,status_code,status').\", \"required\": false, \"location\": \"query\"}}, \"response\": \"{id, status_code: 'EXPIRED'|'ERROR'|'FINISHED'|'IN_PROGRESS'|'PUBLISHED', status (string \\u2014 human-readable status message, present on ERROR)}\", \"url\": \"https://graph.facebook.com/v25.0/{containerId}\"}, {\"id\": \"docusign.workspaces.create\", \"method\": \"POST\", \"description\": \"Provision a new document collaboration workspace within the account.\", \"parameters\": {\"accountId\": {\"type\": \"string\", \"description\": \"The DocuSign account ID.\", \"required\": true, \"location\": \"path\", \"default\": \"default\"}}, \"request\": \"{name: string, description: string, ownerName: string, ownerEmail: string}\", \"response\": \"Created Workspace resource.\", \"url\": \"https://demo.docusign.net/restapi/v2.1/accounts/{accountId}/workspaces\"}], \"count\": 5}"
