    "text": "{\"results\": [{\"id\": \"gmail.users.threads.get\", \"method\": \"GET\", \"description\": \"Retrieve a full email thread along with every message it contains.\", \"parameters\": {\"userId\": {\"type\": \"string\", \"required\": true, \"location\": \"path\", \"default\": \"me\"}, \"id\": {\"type\": \"string\", \"required\": true, \"location\": \"path\"}, \"format\": {\"type\": \"string\", \"enum\": [\"full\", \"minimal\", \"metadata\"], \"description\": \"Response detail level: full (complete message data, default), minimal (IDs and labels only), or metadata (IDs, labels, and headers).\", \"required\": false, \"location\": \"query\"}}, \"response\": \"Thread: {id, snippet, messages: [Message]}\", \"url\": \"https://gmail.googleapis.com/gmail/v1/users/{userId}/threads/{id}\"}, {\"id\": \"slack.reactions.get\", \"method\": \"GET\", \"description\": \"Retrieve all emoji reactions on a message.\", \"parameters\": {\"channel\": {\"type\": \"string\", \"description\": \"Channel where the target message was posted.\", \"required\": true, \"location\": \"query\"}, \"timestamp\": {\"type\": \"string\", \"description\": \"Timestamp of the message whose reactions to retrieve.\", \"required\": true, \"location\": \"query\"}, \"full\": {\"type\": \"boolean\", \"description\": \"When true, returns the complete list of reacting users.\", \"required\": false, \"location\": \"query\"}}, \"response\": {\"ok\": true, \"message\": \"Message\"}, \"url\": \"https://slack.com/api/reactions.get\"}, {\"id\": \"gmail.users.messages.get\", \"method\": \"GET\", \"description\": \"Fetch a specific email message by its ID.\", \"parameters\": {\"userId\": {\"type\": \"string\", \"required\": true, \"location\": \"path\", \"default\": \"me\"}, \"id\": {\"type\": \"string\", \"description\": \"Unique identifier of the message to fetch.\", \"required\": true, \"location\": \"path\"}, \"format\": {\"type\": \"string\", \"enum\": [\"full\", \"minimal\", \"raw\", \"metadata\"], \"description\": \"Response format: full (default), minimal, raw, or metadata.\", \"required\": false, \"location\": \"query\"}}, \"response\": \"Message object with full payload\", \"url\": \"https://gmail.googleapis.com/gmail/v1/users/{userId}/messages/{id}\"}, {\"id\": \"recruitee.offers.list\", \"method\": \"GET\", \"description\": \"Retrieve all offers (jobs and talent pools) for the company.\", \"parameters\": {\"company_id\": {\"type\": \"integer\", \"description\": \"Company ID or subdomain.\", \"required\": true, \"location\": \"path\"}, \"scope\": {\"type\": \"string\", \"enum\": [\"active\", \"archived\", \"closed\", \"draft\", \"published\"], \"description\": \"Filter offers by their current status.\", \"location\": \"query\"}, \"view_mode\": {\"type\": \"string\", \"enum\": [\"brief\", \"full\"], \"description\": \"Level of detail in the response.\", \"location\": \"query\"}}, \"response\": \"{offers: [Offer, ...]}\", \"url\": \"https://api.recruitee.com/c/{company_id}/recruitee/v1/c/{company_id}/offers\"}, {\"id\": \"salesforce.report.run\", \"method\": \"GET\", \"description\": \"Execute a Salesforce report and return the results.\", \"parameters\": {\"reportId\": {\"type\": \"string\", \"description\": \"The identifier of the report to run.\", \"required\": true, \"location\": \"path\"}, \"includeDetails\": {\"type\": \"boolean\", \"description\": \"When true, includes row-level detail records in the result.\", \"required\": false, \"location\": \"query\"}}, \"response\": \"Report result with fact_map, groupings, and aggregates\", \"url\": \"https://yourinstance.salesforce.com/services/data/v61.0/analytics/reports/{reportId}\"}], \"count\": 5}"
